import React, { useState, useEffect, useRef, useCallback } from 'react';
import PropTypes from 'prop-types';
import './Modal.css';

/**
 * InfoModal component que cumple con estándares ISO 25010
 * Modal informativo para mostrar detalles de terapias
 * @param {Object} props - Props del componente
 * @param {boolean} props.isOpen - Estado de apertura del modal
 * @param {Function} props.onRequestClose - Función para cerrar modal
 * @param {Object} props.selectedTerapia - Objeto con información de la terapia
 * @param {Function} props.handleNavigation - Función de navegación
 * @param {string} props.activeContent - Contenido activo actual
 * @param {Function} props.onError - Callback para manejo de errores
 * @param {string} props.loadingText - Texto mostrado durante carga
 * @param {string} props.actionButtonText - Texto del botón de acción
 */
const InfoModal = ({ 
  isOpen, 
  onRequestClose, 
  selectedTerapia, 
  handleNavigation, 
  activeContent,
  onError = null,
  loadingText = "Cargando...",
  actionButtonText = "Saber Más"
}) => {
  const modalRef = useRef(null);
  const previousActiveElement = useRef(null);
  const [imageLoaded, setImageLoaded] = useState(false);
  const [imageVisible, setImageVisible] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [isNavigating, setIsNavigating] = useState(false);

  // Validación y normalización de props
  const onClose = useCallback(() => {
    if (typeof onRequestClose === 'function') {
      onRequestClose();
    }
  }, [onRequestClose]);

  // Manejo de errores interno
  const handleError = useCallback((errorMessage, errorObject = null) => {
    setError(errorMessage);
    if (onError && typeof onError === 'function') {
      onError(errorMessage, errorObject);
    }
    console.error('InfoModal Error:', errorMessage, errorObject);
  }, [onError]);

  // Gestión del scroll del body y foco
  useEffect(() => {
    if (isOpen) {
      // Guardar elemento activo antes de abrir modal
      previousActiveElement.current = document.activeElement;
      document.body.style.overflow = 'hidden';
      setImageVisible(true);
      setError(null); // Limpiar errores al abrir
    } else {
      document.body.style.overflow = '';
      setIsNavigating(false);
      // Restaurar foco al elemento anterior
      if (previousActiveElement.current && previousActiveElement.current.focus) {
        previousActiveElement.current.focus();
      }
    }

    return () => {
      document.body.style.overflow = '';
    };
  }, [isOpen]);

  // Manejo de tecla Escape
  useEffect(() => {
    const handleEscape = (e) => {
      if (e.key === 'Escape' && isOpen && !isNavigating) {
        onClose();
      }
    };

    if (isOpen) {
      document.addEventListener('keydown', handleEscape);
    }

    return () => {
      document.removeEventListener('keydown', handleEscape);
    };
  }, [isOpen, onClose, isNavigating]);

  // Gestión de foco para accesibilidad
  useEffect(() => {
    if (isOpen && modalRef.current) {
      const focusableElements = modalRef.current.querySelectorAll(
        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
      );

      if (focusableElements.length > 0) {
        focusableElements[0].focus();
      }

      // Trap focus dentro del modal
      const handleTabKey = (e) => {
        if (e.key === 'Tab') {
          const firstElement = focusableElements[0];
          const lastElement = focusableElements[focusableElements.length - 1];

          if (e.shiftKey && document.activeElement === firstElement) {
            e.preventDefault();
            lastElement.focus();
          } else if (!e.shiftKey && document.activeElement === lastElement) {
            e.preventDefault();
            firstElement.focus();
          }
        }
      };

      modalRef.current.addEventListener('keydown', handleTabKey);

      return () => {
        if (modalRef.current) {
          modalRef.current.removeEventListener('keydown', handleTabKey);
        }
      };
    }
  }, [isOpen]);

  // Manejo de clic fuera del modal
  const handleClickOutside = useCallback((e) => {
    if (e.target.classList.contains('modal-container') && !isNavigating) {
      onClose();
    }
  }, [onClose, isNavigating]);

  // Handlers para la imagen con manejo de errores
  const handleImageLoad = useCallback(() => {
    setImageLoaded(true);
    setIsLoading(false);
  }, []);

  const handleImageError = useCallback(() => {
    setImageVisible(false);
    setIsLoading(false);
    handleError('Error al cargar la imagen', new Error('Image load failed'));
  }, [handleError]);

  // Handler para navegar a servicios con validación
  const handleNavigateToServices = useCallback(async () => {
    try {
      setIsNavigating(true);
      setError(null);

      // Validar función de navegación
      if (typeof handleNavigation !== 'function') {
        throw new Error('Función de navegación no disponible');
      }

      // Simular delay de navegación para UX
      await new Promise(resolve => setTimeout(resolve, 300));

      // Cerrar modal antes de navegar
      onClose();

      // Navegar a services
      handleNavigation("services");

    } catch (error) {
      handleError('Error al navegar. Intente nuevamente.', error);
    } finally {
      setIsNavigating(false);
    }
  }, [handleNavigation, onClose, handleError]);

  // Inicializar carga de imagen cuando se abre el modal
  useEffect(() => {
    if (isOpen && selectedTerapia?.image) {
      setIsLoading(true);
      setImageLoaded(false);
    }
  }, [isOpen, selectedTerapia?.image]);

  // No renderizar si no hay terapia seleccionada o el modal está cerrado
  if (!selectedTerapia || !isOpen) {
    return null;
  }

  // Extraer y validar propiedades de la terapia
  const { 
    title = 'Terapia', 
    description = 'Descripción no disponible', 
    image = '' 
  } = selectedTerapia;

  // Validar que la descripción no esté vacía
  const safeDescription = description.trim() || 'Información detallada no disponible en este momento.';

  return (
    <div
      className={`modal-container info-modal ${isOpen ? 'show' : ''}`}
      onClick={handleClickOutside}
      role="dialog"
      aria-modal="true"
      aria-labelledby="info-modal-title"
      aria-describedby="info-modal-description"
      ref={modalRef}
    >
      <div
        className={`modal-content info-modal-content ${isOpen ? 'fade-in' : 'fade-out'}`}
        onClick={(e) => e.stopPropagation()}
        role="document"
      >
        {/* Encabezado del modal */}
        <div className="modal-header">
          <h2 
            id="info-modal-title" 
            className="modal-title info-modal-title"
          >
            {title}
          </h2>
          <button 
            className="btn-close" 
            onClick={onClose}
            aria-label={`Cerrar información de ${title}`}
            title="Cerrar (Escape)"
            disabled={isNavigating}
          >
            ✖
          </button>
        </div>

        {/* Contenido principal del modal */}
        <div className="modal-body info-modal-body">
          {/* Contenedor de imagen */}
          {imageVisible && image && (
            <div className="info-modal-image-container">
              {isLoading && (
                <div className="image-loading-overlay">
                  <div className="spinner" aria-hidden="true"></div>
                  <span className="sr-only">Cargando imagen...</span>
                </div>
              )}
              <img
                src={image}
                alt={`Imagen ilustrativa de ${title}`}
                className={`info-modal-image ${imageLoaded ? 'loaded' : 'loading'}`}
                onLoad={handleImageLoad}
                onError={handleImageError}
                loading="lazy"
              />
            </div>
          )}

          {/* Contenedor de descripción */}
          <div className="info-modal-description-container">
            <div 
              id="info-modal-description"
              className="info-modal-description"
              role="region"
              aria-label="Descripción de la terapia"
            >
              <p>{safeDescription}</p>
            </div>
          </div>
        </div>

        {/* Mensaje de error */}
        {error && (
          <div 
            className="error-message" 
            role="alert"
            aria-live="assertive"
          >
            <p className="text-danger">
              ⚠️ {error}
            </p>
          </div>
        )}

        {/* Pie del modal */}
        <div className="modal-footer">
          <button
            className={`btn btn-primary info-modal-action-btn ${isNavigating ? 'btn-loading' : ''}`}
            onClick={handleNavigateToServices}
            disabled={isNavigating}
            aria-describedby="action-button-description"
          >
            {isNavigating ? (
              <>
                <span className="btn-spinner" aria-hidden="true"></span>
                Navegando...
              </>
            ) : (
              actionButtonText
            )}
          </button>
          <div 
            id="action-button-description" 
            className="sr-only"
          >
            Navegar a la página de servicios para más información
          </div>
        </div>
      </div>
    </div>
  );
};

// Definición de PropTypes para validación
InfoModal.propTypes = {
  isOpen: PropTypes.bool.isRequired,
  onRequestClose: PropTypes.func.isRequired,
  selectedTerapia: PropTypes.shape({
    title: PropTypes.string,
    description: PropTypes.string,
    image: PropTypes.string,
  }),
  handleNavigation: PropTypes.func,
  activeContent: PropTypes.string,
  onError: PropTypes.func,
  loadingText: PropTypes.string,
  actionButtonText: PropTypes.string,
};

// Valores por defecto
InfoModal.defaultProps = {
  selectedTerapia: null,
  handleNavigation: null,
  activeContent: '',
  onError: null,
  loadingText: "Cargando...",
  actionButtonText: "Saber Más",
};

export default InfoModal;
